// OpenNext's custom worker: https://opennext.js.org/cloudflare/howtos/custom-worker
// It exports the ChatRoom Durable Object from the main module and sends WebSocket upgrades on /chat/<room> to the room;
// everything else is the Next.js app.
// @ts-expect-error `.open-next/worker.js` is generated by `opennextjs-cloudflare build`
import { default as handler } from './.open-next/worker.js'

export { ChatRoom } from './src/chat/ChatRoom'

const ROOM = /^\/chat\/([^/]+)$/

export default {
  fetch(request, env, ctx) {
    const room = ROOM.exec(new URL(request.url).pathname)?.[1]
    if (room && request.headers.get('Upgrade') === 'websocket') {
      return env.CHAT_ROOM.getByName(decodeURIComponent(room)).fetch(request)
    }
    return handler.fetch(request, env, ctx)
  },
} satisfies ExportedHandler<CloudflareEnv>
